/**
 * Every .env setting, parsed once. `.env.example` documents what each does.
 */
// ----- Contents (generated by `npm run index` — do not edit) -----
// L17   Settings
// L21     env
// L24     list()
// L27     fail()
// L33     setting()
// L39     required()
// L46     number()
// L53     config
// ----- end of contents -----

import 'dotenv/config'

// =============================================================================
//   Settings
// =============================================================================

const env = process.env

/** "a, b,,c" -> ['a', 'b', 'c'] */
const list = (v = '') => v.split(',').map((s) => s.trim()).filter(Boolean)

/** Stops startup with a message pointing at .env. */
function fail (message) {
  console.error(`${message} — see .env.example for what it does.`)
  process.exit(1)
}

/** The setting's text; its line must exist in .env, but may be blank. */
function setting (name) {
  if (env[name] === undefined) fail(`${name} is missing from .env`)
  return env[name].trim()
}

/** A setting that must be filled in. */
function required (name) {
  const v = setting(name)
  if (!v) fail(`${name} is empty in .env`)
  return v
}

/** A setting that must be a whole number of at least `min`. */
function number (name, min = 1) {
  const v = required(name)
  if (!/^\d+$/.test(v) || Number(v) < min) fail(`${name} in .env must be a whole number of at least ${min}, not "${v}"`)
  return Number(v)
}

/** All settings, read from .env only (no defaults in code). Import this rather than reading process.env. */
export const config = {
  token: required('BOT_TOKEN'),
  applicationId: required('APPLICATION_ID'),
  // Blank = register /meson-query globally instead of in one server.
  guildId: setting('GUILD_ID'),

  // Auto-reply only in channels (and their threads) under these categories.
  replyCategories: new Set(list(required('REPLY_CATEGORY_IDS'))),

  // Other bots' messages (Ticket Tool's form embed) read at the start of a ticket.
  scanLimit: number('AUTO_SCAN_MESSAGES'),

  // Members with any of these roles are ignored in tickets (they paste IDs while investigating).
  staffRoles: new Set(list(setting('STAFF_ROLE_IDS'))),

  // Wallet-only tickets: how far back to look for unfinished swaps.
  addressLookbackDays: number('ADDRESS_LOOKBACK_DAYS'),
  addressMaxPages: number('ADDRESS_MAX_PAGES'),

  // Background re-checks of a posted swap: fast at first, then slower. The first interval is also how often the shared check round runs (watch.js). An interval of 0 turns them off.
  watchIntervalMs: number('SWAP_WATCH_INTERVAL_SECONDS', 0) * 1000,
  watchSlowerAfterMs: number('SWAP_WATCH_SLOWER_AFTER_MINUTES') * 60 * 1000,
  watchSlowerIntervalMs: number('SWAP_WATCH_SLOWER_INTERVAL_SECONDS') * 1000,
  watchSlowestAfterMs: number('SWAP_WATCH_SLOWEST_AFTER_MINUTES') * 60 * 1000,
  watchSlowestIntervalMs: number('SWAP_WATCH_SLOWEST_INTERVAL_SECONDS') * 1000,
  watchMaxMs: number('SWAP_WATCH_MAX_HOURS') * 60 * 60 * 1000,

  // Meson API requests: give up on one after this long; retry errors this many times (waits about 1s, 2s, 4s, …, jittered).
  mesonTimeoutMs: number('MESON_TIMEOUT_SECONDS') * 1000,
  mesonRetries: number('MESON_RETRIES', 0),
  // If Meson still errors after those retries, handle the whole ticket message (or a ticket's restart recovery) again later — until it works, waiting twice as long each time up to the cap.
  ticketRetryMs: number('TICKET_RETRY_SECONDS') * 1000,
  ticketRetryMaxMs: number('TICKET_RETRY_MAX_SECONDS') * 1000,

  // Network notice on unfinished swaps: re-check Meson's chain health (rpcs.meson.fi) at most this often. 0 = no notices.
  chainHealthMs: number('CHAIN_HEALTH_CACHE_SECONDS', 0) * 1000,

  // Every repeated wait (swap re-checks, retries) is made randomly up to this many percent shorter or longer, so requests never come at a fixed beat. 0 = exact intervals.
  jitterPercent: number('JITTER_PERCENT', 0),
}

if (config.jitterPercent > 90) fail('JITTER_PERCENT in .env must be at most 90')

if (config.ticketRetryMaxMs < config.ticketRetryMs) fail('TICKET_RETRY_MAX_SECONDS in .env must not be below TICKET_RETRY_SECONDS')

// The slow-down stages must come in order, or the middle one is silently skipped.
if (config.watchSlowestAfterMs < config.watchSlowerAfterMs) fail('SWAP_WATCH_SLOWEST_AFTER_MINUTES in .env must not be below SWAP_WATCH_SLOWER_AFTER_MINUTES')
